/*
 * قوالب المخطط الموسمي — رياضات فنية وفردية متنوعة
 * ==================================================
 * جمباز، تسلق، تزلج على الجليد (إعداد قبل الموسم)، جولف، رقص، يوجا (مبتدئ)،
 * بيلاتس (مبتدئ)، تشيرليدنج، تزلج فني على الجليد، فروسية (لياقة الفارس)،
 * رماية بالقوس، رماية بالسلاح، تزلج بالعجل (سرعة)، باركور.
 * كل قالب: فترات ← بلوكات ← أسابيع (حمل ١-١٠) ← تمرينات مفصلة بالشدة والحجم والراحة والهدف.
 */

/* ---------- أدوات مساعدة (بترجع نسخة جديدة كل مرة) ---------- */
const t = (ar, en) => ({ ar, en });
const W = (ar, en, x) => ({ kind: 'warmup', name: t(ar, en), ...x });
const wl = (libId, x) => ({ kind: 'warmup', libId, ...x });
const M = (ar, en, x) => ({ kind: 'mobility', name: t(ar, en), ...x });
const ml = (libId, x) => ({ kind: 'mobility', libId, ...x });
/* تمرين أساسي: ref = id من المكتبة أو [عربي، إنجليزي]، p = [الهدف عربي، إنجليزي]، c = العنصر */
const mainItem = (kind) => (ref, x, p, c) => ({
  kind,
  ...(typeof ref === 'string' ? { libId: ref } : { name: t(ref[0], ref[1]) }),
  ...x,
  purpose: t(p[0], p[1]),
  component: c
});
const S = mainItem('strength');
const D = mainItem('drill');
const T = mainItem('timed');
const R = mainItem('run');
const ses = (ar, en, gar, gen, components, rpe, duration, items) => ({ title: t(ar, en), goal: t(gar, gen), components, rpe, duration, items });
const blk = (ar, en, gar, gen, components, loads, weekTypes, pattern) => ({ name: t(ar, en), goal: t(gar, gen), components, loads, weekTypes, pattern });
const per = (type, gar, gen, components, blocks) => ({ type, goal: t(gar, gen), components, blocks });

/* ---------- إحماء وتهدئة مشتركة ---------- */
const genWU = (min) => [
  W('جري خفيف + حركات ديناميكية (سكيب، جري جانبي، كاريوكا)', 'Easy jog + dynamic drills (skips, side shuffle, carioca)', { duration: (min || 8) + 'min' }),
  wl('wg_worlds_greatest_stretch', { sets: 1, reps: '4/side' }),
  wl('ex_leg_swings', { sets: 1, reps: '10/leg each plane' })
];
const gymWU = () => [
  W('عجلة ثابتة أو روينج خفيف', 'Easy bike or rower', { duration: '6min' }),
  wl('ad_90_90_hip_switches', { sets: 1, reps: '6/side' }),
  wl('wg_scapular_push_up', { sets: 1, reps: '10' }),
  wl('ex_band_pull_apart', { sets: 1, reps: '15' })
];
const wristWU = () => wl('ad_wrist_active_range_of_motion', { sets: 1, reps: '10 each direction', note: t('على الأرض بوزن الجسم: أمام، ورا، جنب، ودوائر', 'Loaded on the floor: forward, back, sideways and circles') });
const stretchCD = (min, ar, en) => M(ar || 'تهدئة: إطالات ثابتة للعضلات اللي اشتغلت', en || 'Cool-down: static stretching for the worked muscles', { duration: (min || 8) + 'min' });
const breathCD = (min) => M('تنفس بطيء بالبطن (٤ ثواني شهيق / ٦ زفير) وأنت نايم على ضهرك', 'Slow belly breathing (4s in / 6s out) lying supine', { duration: (min || 3) + 'min' });

