      'هبوط آمن وصامت من ارتفاعات أعلى، دقة في قفزات البريسيجن لمسافات أطول، فولتات وكلايم أب أسرع، وقوة نسبية لوزن الجسم، وربطهم في خطوط (لاينز) سلسة، مع تحكم في عدد لمسات الأرض لحماية الأوتار.',
      'Safe, quiet landings from greater heights, accurate precision jumps over longer distances, faster vaults and climb-ups, and strength relative to bodyweight, linked into smooth lines, with ground-contact counts controlled to protect the tendons.'
